{"version":3,"sources":["plugins/footnote/assets/stylesheets/footnotes.scss"],"names":[],"mappings":"AAAA,kBACE,6BAAA,CAEA,oCACE,wBAAA,CAAA,gBAAA,CACA,oBAAA,CAEA,2CACE,gBAAA,CACA,oBAAA,CACA,wCAAA,CACA,oBAAA,CACA,gBAAA,CACA,aAAA,CACA,iCAAA,CAIJ,mCACE,oBAAA,CAKF,mEAEE,iBAAA,CAIA,MAAA,CACA,OAAA,CAGF,mGAGE,YAAA,CAIJ,wDACE,wBAAA,CACA,4BAAA,CAEA,qFACE,qBAAA,CAGF,4DACE,gBAAA,CACA,cAAA,CAGF,0DACE,QAAA,CACA,WAAA,CACA,cAAA,CAIJ,aACE,kCAAA,CAEA,uBACE,oBAAA,CAEA,8BACE,gBAAA,CACA,oBAAA,CACA,6CAAA,CACA,oBAAA,CACA,gBAAA,CACA,aAAA,CACA,sCAAA,CAIJ,+BACE,WAAA,CAIA,cAAA,CACA,cAAA,CACA,aAAA,CACA,MAAA,CACA,OAAA,CACA,QAAA,CACA,YAAA,CACA,iBAAA,CACA,kCAAA,CACA,oCAAA,CACA,YAAA,CAEA,4CACE,6CAAA,CAGF,uCACE,SAAA,CACA,WAAA,CACA,iBAAA,CACA,wCAAA,CACA,gBAAA,CACA,4BAAA","file":"output.css","sourcesContent":[".inline-footnotes {
  counter-reset: inline-footnote;

  a.expand-footnote {
    user-select: none;
    display: inline-block;

    &::after {
      padding: 0 0.125em;
      display: inline-block;
      content: "[" counter(inline-footnote) "]";
      vertical-align: super;
      font-size: 0.75rem;
      line-height: 1;
      counter-increment: inline-footnote;
    }
  }

  .inline-footnote {
    display: inline-block;
  }

  // This is hack to work with lazy-loading, we will trick the browser
  // to believe the image is in the DOM and can be loaded
  .footnotes-list,
  .footnotes-sep {
    position: absolute;

    // the left/right positioning prevents overflow issues
    // with long words causing overflow on small screens
    left: 0;
    right: 0;
  }

  .footnotes-sep,
  .footnotes-list,
  .footnote-ref {
    display: none;
  }
}

.fk-d-tooltip__content[data-identifier="inline-footnote"] {
  overflow-wrap: break-word;
  font-size: var(--font-down-1);

  .fk-d-tooltip__inner-content {
    flex-direction: column;
  }

  img {
    object-fit: cover;
    max-width: 100%;
  }

  p {
    margin: 0;
    min-width: 0;
    max-width: 100%;
  }
}

.ProseMirror {
  counter-reset: prosemirror-footnote;

  .footnote {
    display: inline-block;

    &::after {
      padding: 0 0.125em;
      display: inline-block;
      content: "[" counter(prosemirror-footnote) "]";
      vertical-align: super;
      font-size: 0.75rem;
      line-height: 1;
      counter-increment: prosemirror-footnote;
    }
  }

  .footnote-tooltip {
    cursor: auto;

    // Position is fixed to be relative to the .ProseMirror editor
    // See https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Display/Containing_block#identifying_the_containing_block
    position: fixed;
    max-height: 40%;
    overflow: auto;
    left: 0;
    right: 0;
    bottom: 0;
    margin: 0.5rem;
    padding-top: 0.5rem;
    background-color: var(--primary-50);
    border-radius: var(--d-border-radius);
    z-index: z("modal", "tooltip");

    &:focus-within {
      outline: 1px solid var(--content-border-color);
    }

    &::before {
      top: 0.1rem;
      left: 0.25rem;
      position: absolute;
      content: "[" var(--footnote-counter) "]:";
      font-size: 0.75rem;
      color: var(--primary-low-mid);
    }
  }
}
"]}

