    grid-area: replies;
  }
}
",":root {
  --channel-list-avatar-size: 43px;
}

.chat-channel-row {
  margin: 0;
  border-radius: 0;
  border-bottom: 1px solid var(--content-border-color);
  transition:
    height 0.25s ease-in-out,
    opacity 0.25s ease-out;
  transform-origin: top center;
  will-change: height, opacity, left;
  position: relative;
  height: 4em;

  &.-fade-out {
    .chat-channel-row__content {
      background-color: var(--danger-low);
    }
    height: 0 !important;
    overflow: hidden;
    opacity: 0.5 !important;
  }

  &__content {
    padding-inline: 1.5rem;
    padding-block: 0.5rem;
    z-index: 2;
    box-sizing: border-box;
    transition: border-radius 0.25s ease-in-out;

    // for sliding delete animation
    background: var(--secondary);
    height: 100%;

    &.-animate-reset {
      transition: margin-right 0.15s ease-out;
      margin-right: 0 !important;
    }

    &:not(.-animate-reset) {
      border-top-right-radius: 0.25rem;
      border-bottom-right-radius: 0.25rem;
    }
  }

  &__info {
    .is-category & {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-grow: 1;
    }

    .is-dm & {
      display: grid;
      grid-template-areas:
        "name metadata"
        "msg msg";
      grid-template-columns: auto 1fr;
      width: 100%;
      align-items: center;
    }
  }

  &__action-btn {
    z-index: 1;
    display: flex;
    justify-content: flex-end;
    align-items: center;
    position: absolute;
    top: 0;
    bottom: 0;
    right: 0;
    left: 0;

    &.--remove {
      background: var(--danger);
      color: var(--primary-very-low);
    }

    &.--clear {
      background: var(--tertiary);
      color: var(--secondary);
    }

    .d-icon {
      transform-origin: 50% 50%;
      transform-box: fill-box;
      transition: scale 0.2s ease-out;
      margin-inline: 0 1.5rem;
    }

    &.-not-at-threshold {
      .d-icon {
        scale: 0.7;
      }
    }

    &.-at-threshold {
      .d-icon {
        scale: 1.5;
      }
    }
  }

  .chat-channel {
    &__user-info,
    &__channel-info {
      grid-area: name;
    }

    &__metadata {
      grid-area: metadata;

      .chat-channel-unread-indicator {
        font-size: var(--font-down-2);
        margin-top: 0.25rem;
      }
    }

    &__metadata-date {
      font-size: var(--font-down-2);
    }

    &__last-message {
      @include ellipsis;
      grid-area: msg;
      color: var(--primary-high);

      .emoji {
        width: 1em;
        height: 1em;
      }
    }
  }

  .chat-channel-icon {
    &.--users-count {
      font-size: var(--font-up-2);
    }
  }
}
",".c-channel-info {
  .c-back-button {
    padding-bottom: 1em;
  }
}

.c-channel-members {
  width: 100%;
}
",".c-channel-settings {
  min-width: 320px;

  html.footer-nav-ipad &,
  html.footer-nav-visible & {
    padding-bottom: calc(
      env(safe-area-inset-bottom) + var(--footer-nav-height, 0px)
    );
  }
}
",".c-channel-search {
  html.footer-nav-ipad &,
  html.footer-nav-visible & {
    padding-bottom: calc(
      env(safe-area-inset-bottom) + var(--footer-nav-height, 0px)
    );
  }
}
",".chat-form {
  &__section {
    margin-bottom: 0;

    &:last-of-type {
      .chat-form__section-content {
        background: none;
        padding-left: 0;
      }
    }

    &-content {
      background: var(--primary-very-low);
      padding: 1rem;
    }
  }

  &__section-title {
    .chat-form__section:not(:first-of-type) & {
      margin-top: 1.5rem;
    }
  }

  &__row-content {
    min-height: 40px;
  }
}
",".chat-modal-thread-settings {
  .thread-title-length {
    color: var(--primary-medium);
    margin-bottom: 1rem;
    text-align: right;
  }

  .discourse-ai-cta {
    padding: 1rem 1.25rem;
    border-radius: 0.25rem;
    background-color: var(--primary-very-low);
    border: 1px solid var(--content-border-color);
    margin-top: 5rem;

    p {
      margin: 0;
    }

    &__title {
      font-weight: bold;
    }

    &__description {
      font-size: var(--font-down-1);
    }
  }
}
",".c-navbar {
  &-container {
    max-width: 100vw;
  }

  &__back-button {
    justify-content: flex-start;
    box-sizing: border-box;
  }

  &__title {
    padding-left: 0.3rem;
  }
}
",".chat-thread-list-header {
  padding-inline: 0 0.5rem;
  align-items: flex-start;

  &__label {
    padding-top: 0.35em;
  }

  &__label-channel {
    line-height: var(--line-height-small);
  }
}
",".c-user-thread {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-inline: 0;
  padding: 0.5rem 1.5rem;

  .chat-channel-icon {
    grid-area: avatar;
    position: relative;

    .avatar {
      margin-top: 4px;
      width: var(--channel-list-avatar-size);
      height: var(--channel-list-avatar-size);
    }
  }

  .c-user-thread__link {
    display: grid;
    column-gap: 0.75em;
    grid-template-columns: 1fr auto;
    margin-inline: 0;
    width: 100%;
    grid-template-areas:
      "category timestamp"
      "title title"
      "excerpt excerpt";
  }

  .avatar-flair.--threads {
    position: absolute;
    top: -4px;
    right: -3px;
    background: var(--primary-low);
    border-radius: 50%;
    padding: 0.2em;
    line-height: var(--line-height-small);
    border: 2px solid var(--secondary-very-high);
    color: var(--primary-high);
  }

  .chat__thread-title-container {
    display: flex;
    grid-area: title;

    .chat__thread-title {
      @include ellipsis;

      &__name {
        @include ellipsis;
      }
    }
  }

  .chat-channel-title {
    grid-area: category;
  }

  .chat-message-thread-indicator__last-reply-timestamp {
    grid-area: timestamp;
    font-size: var(--font-down-2-rem);
    align-self: center;
  }

  .c-user-thread__excerpt {
    @include ellipsis;
    grid-area: excerpt;
    display: flex;
    color: var(--primary-high);
  }

  .c-user-thread__excerpt-text {
    margin-left: 0.25em;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}
",".has-full-page-chat {
  .d-header-icons .search-dropdown,
  .d-header-icons .hamburger-dropdown {
    display: none;
  }

  .home-logo-wrapper-outlet {
    width: 100%;
  }

  .c-header {
    width: 100%;
    display: flex;
    align-items: center;

    .back-to-forum {
      color: var(--primary);
      font-size: var(--font-up-1);
      padding: 0.5rem 0.8rem 0.5rem 0.25rem;

      .d-icon {
        color: var(--primary);
      }
    }

    .c-heading {
      color: var(--primary);
      font-size: var(--font-up-2);
      font-weight: bold;
      margin: 0 auto;
      padding: 0.4rem 0.8rem;
    }
  }
}
",".full-page-chat {
  #main-chat-outlet.chat-view {
    height: calc(
      100dvh - var(--main-outlet-offset) - var(--composer-height, 0px)
    );
    display: grid;
    grid-template-rows: 1fr auto;
    grid-template-areas:
      "list"
      "footer";
  }

  .channels-list {
    grid-area: list;
    padding-bottom: 0;
  }

  .c-routes {
    grid-area: list;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }
}

.c-footer {
  position: relative;

  &__item {
    .c-unread-indicator,
    .c-unread-indicator.-urgent {
      margin-left: 1rem;
    }

    &.--active {
      .full-page-chat & {
        .d-icon,
        .d-button-label {
          color: var(--d-nav-color--active);
        }
      }
    }
  }
}
"]}

